"""ORD_LINE renumbering migration for Meridian CRM 4.2 semantics."""

from decimal import Decimal


def _numeric_line_no(value: object) -> Decimal:
    """Apply legacy numeric-context coercion: an empty string is zero."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted lines and assign contiguous line numbers per order."""
    surviving: list[tuple[str, Decimal, int, dict]] = []

    for position, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue

        ord_id = str(row.get("ORD_ID", ""))
        line_no = _numeric_line_no(row.get("LINE_NO", ""))
        surviving.append((ord_id, line_no, position, row))

    surviving.sort(key=lambda item: (item[0], item[1], item[2]))

    result: list[dict] = []
    current_ord_id: str | None = None
    next_line_no = 0

    for ord_id, _old_line_no, _position, row in surviving:
        if ord_id != current_ord_id:
            current_ord_id = ord_id
            next_line_no = 1
        else:
            next_line_no += 1

        new_row = dict(row)
        new_row["LINE_NO"] = next_line_no
        result.append(new_row)

    return result
